enum Basic {
  BasicZero,
  BasicOne,
  BasicFive = 5,
  BasicSix,
  BasicNegative = -2,
  BasicNegativeNext,
  BasicAlias = BasicFive,
  BasicMask = BasicAlias | 8
};

struct EnumHolder {
  enum { NestedFirst = 3, NestedAlias = NestedFirst } value;
};

